#![deny(clippy::all)]

use core::convert::TryInto;
use solana_program::{
    account_info::AccountInfo,
    entrypoint,
    entrypoint::ProgramResult,
    program_error::ProgramError,
    pubkey::Pubkey,
};

entrypoint!(process_instruction);

pub fn process_instruction(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    instruction_data: &[u8],
) -> ProgramResult {
    if instruction_data.len() < 8 {
        return Err(ProgramError::InvalidInstructionData);
    }

    let (disc, data) = instruction_data.split_at(8);
    route(program_id, accounts, disc, data)
}

fn route(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    disc: &[u8],
    data: &[u8],
) -> ProgramResult {
    if disc == &[175, 175, 109, 31, 13, 152, 155, 237] {
        return initialize(program_id, accounts, data);
    }
    if disc == &[11, 18, 104, 9, 104, 174, 59, 33] {
        return increment(program_id, accounts, data);
    }
    if disc == &[106, 227, 168, 59, 248, 27, 150, 101] {
        return decrement(program_id, accounts, data);
    }
    if disc == &[23, 81, 251, 84, 138, 183, 240, 214] {
        return reset(program_id, accounts, data);
    }
    Err(ProgramError::InvalidInstructionData)
}

fn initialize(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    data: &[u8],
) -> ProgramResult {
    let counter = accounts.get(0).ok_or(ProgramError::NotEnoughAccountKeys)?;
    let authority = accounts.get(1).ok_or(ProgramError::NotEnoughAccountKeys)?;

    if !authority.is_signer {
        return Err(ProgramError::MissingRequiredSignature);
    }
    // Args
    if data.len() < 8 {
        return Err(ProgramError::InvalidInstructionData);
    }
    let start_value: u64 = u64::from_le_bytes(data[0..8].try_into().unwrap());
    let counter_bump = bump_seed(program_id, &[b"counter", authority.key.as_ref()], counter.key)?;
    if counter.owner != program_id {
        return Err(ProgramError::IncorrectProgramId);
    }
    if !counter.is_writable {
        return Err(ProgramError::InvalidAccountData);
    }
    let counter_state = CounterAccount {
        authority: *authority.key,
        count: start_value,
        bump: counter_bump,
    };
    CounterAccount::save(counter, &counter_state)?;

    Ok(())
}

fn increment(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    data: &[u8],
) -> ProgramResult {
    let counter = accounts.get(0).ok_or(ProgramError::NotEnoughAccountKeys)?;
    let authority = accounts.get(1).ok_or(ProgramError::NotEnoughAccountKeys)?;

    if !authority.is_signer {
        return Err(ProgramError::MissingRequiredSignature);
    }
    // Args
    if data.len() < 8 {
        return Err(ProgramError::InvalidInstructionData);
    }
    let amount: u64 = u64::from_le_bytes(data[0..8].try_into().unwrap());
    if counter.owner != program_id {
        return Err(ProgramError::IncorrectProgramId);
    }
    if !counter.is_writable {
        return Err(ProgramError::InvalidAccountData);
    }
    let counter_bump = bump_seed(program_id, &[b"counter", authority.key.as_ref()], counter.key)?;
    let mut counter_state = CounterAccount::from_account_info(counter)?;
    if counter_state.authority != *authority.key {
        return Err(ProgramError::InvalidAccountData);
    }
    if counter_state.bump != counter_bump {
        return Err(ProgramError::InvalidSeeds);
    }
    counter_state.count = counter_state
        .count
        .checked_add(amount)
        .ok_or(CounterError::Overflow)?;
    CounterAccount::save(counter, &counter_state)?;

    Ok(())
}

fn decrement(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    data: &[u8],
) -> ProgramResult {
    let counter = accounts.get(0).ok_or(ProgramError::NotEnoughAccountKeys)?;
    let authority = accounts.get(1).ok_or(ProgramError::NotEnoughAccountKeys)?;

    if !authority.is_signer {
        return Err(ProgramError::MissingRequiredSignature);
    }
    // Args
    if data.len() < 8 {
        return Err(ProgramError::InvalidInstructionData);
    }
    let amount: u64 = u64::from_le_bytes(data[0..8].try_into().unwrap());
    if counter.owner != program_id {
        return Err(ProgramError::IncorrectProgramId);
    }
    if !counter.is_writable {
        return Err(ProgramError::InvalidAccountData);
    }
    let counter_bump = bump_seed(program_id, &[b"counter", authority.key.as_ref()], counter.key)?;
    let mut counter_state = CounterAccount::from_account_info(counter)?;
    if counter_state.authority != *authority.key {
        return Err(ProgramError::InvalidAccountData);
    }
    if counter_state.bump != counter_bump {
        return Err(ProgramError::InvalidSeeds);
    }
    counter_state.count = counter_state
        .count
        .checked_sub(amount)
        .ok_or(CounterError::Underflow)?;
    CounterAccount::save(counter, &counter_state)?;

    Ok(())
}

fn reset(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    data: &[u8],
) -> ProgramResult {
    let counter = accounts.get(0).ok_or(ProgramError::NotEnoughAccountKeys)?;
    let authority = accounts.get(1).ok_or(ProgramError::NotEnoughAccountKeys)?;

    if !authority.is_signer {
        return Err(ProgramError::MissingRequiredSignature);
    }
    if !data.is_empty() {
        return Err(ProgramError::InvalidInstructionData);
    }
    if counter.owner != program_id {
        return Err(ProgramError::IncorrectProgramId);
    }
    if !counter.is_writable {
        return Err(ProgramError::InvalidAccountData);
    }
    let counter_bump = bump_seed(program_id, &[b"counter", authority.key.as_ref()], counter.key)?;
    let mut counter_state = CounterAccount::from_account_info(counter)?;
    if counter_state.authority != *authority.key {
        return Err(ProgramError::InvalidAccountData);
    }
    if counter_state.bump != counter_bump {
        return Err(ProgramError::InvalidSeeds);
    }
    counter_state.count = 0;
    CounterAccount::save(counter, &counter_state)?;

    Ok(())
}

#[repr(C)]
pub struct CounterAccount {
    pub authority: Pubkey,
    pub count: u64,
    pub bump: u8,
}

impl CounterAccount {
    pub const DISCRIMINATOR: [u8; 8] = [164, 8, 153, 71, 8, 44, 93, 22];
    pub const LEN: usize = 41;
    pub const TOTAL_LEN: usize = 8 + Self::LEN;

    pub fn read(data: &[u8]) -> Result<Self, ProgramError> {
        if data.len() < Self::TOTAL_LEN {
            return Err(ProgramError::InvalidAccountData);
        }
        if data[..8] != Self::DISCRIMINATOR {
            return Err(ProgramError::InvalidAccountData);
        }
        let mut offset = 8usize;
        let authority: Pubkey = Pubkey::new_from_array(data[offset..offset + 32].try_into().unwrap());
        offset += 32;
        let count: u64 = u64::from_le_bytes(data[offset..offset + 8].try_into().unwrap());
        offset += 8;
        let bump: u8 = data[offset];
        offset += 1;
        Ok(Self { authority, count, bump })
    }

    pub fn write(data: &mut [u8], value: &Self) -> ProgramResult {
        if data.len() < Self::TOTAL_LEN {
            return Err(ProgramError::InvalidAccountData);
        }
        data[..8].copy_from_slice(&Self::DISCRIMINATOR);
        let mut offset = 8usize;
        data[offset..offset + 32].copy_from_slice(value.authority.as_ref());
        offset += 32;
        data[offset..offset + 8].copy_from_slice(&value.count.to_le_bytes());
        offset += 8;
        data[offset] = value.bump as u8;
        offset += 1;
        Ok(())
    }

    pub fn from_account_info(account: &AccountInfo) -> Result<Self, ProgramError> {
        let data = account.try_borrow_data()?;
        Self::read(&data)
    }

    pub fn save(account: &AccountInfo, value: &Self) -> ProgramResult {
        let mut data = account.try_borrow_mut_data()?;
        Self::write(&mut data, value)
    }
}

fn bump_seed(
    program_id: &Pubkey,
    seeds: &[&[u8]],
    expected: &Pubkey,
) -> Result<u8, ProgramError> {
    let (derived, bump) = Pubkey::find_program_address(seeds, program_id);
    if &derived != expected {
        return Err(ProgramError::InvalidSeeds);
    }
    Ok(bump)
}

#[derive(Clone, Copy, Debug, PartialEq)]
#[repr(u32)]
pub enum CounterError {
    /// Counter overflow
    Overflow = 6000,
    /// Counter underflow
    Underflow = 6001,
}

impl From<CounterError> for ProgramError {
    fn from(error: CounterError) -> Self {
        ProgramError::Custom(error as u32)
    }
}